class ImageServer extends obsidian.Component {
    constructor(plugin) {
        super();
        this.settings = plugin.settings;
        this.plugin = plugin;
        this.imgServer = null;
    }
    async onload() {
        super.onload();
        const path = require('path');
        const http = require('http');
        const fs = require('fs');
        let dir = null;
        try {
            dir = path.join(this.plugin.path);
        }
        catch (e) {
            console.log('Couldn\'t start image server. This is likely because we\'re on mobile!');
            console.log(e);
            return;
        }
        const mime = {
            gif: 'image/gif',
            jpg: 'image/jpeg',
            png: 'image/png',
            svg: 'image/svg+xml',
        };
        const settings = this.settings;
        const vault = this.plugin.app.vault;
        this.imgServer = http.createServer(function (req, res) {
            const reqpath = req.url.toString().split('?')[0];
            if (req.method !== 'GET') {
                res.statusCode = 501;
                res.setHeader('Content-Type', 'text/plain');
                return res.end('Method not implemented');
            }
            let file = path.join(dir, decodeURI(reqpath.replace(/\/$/, '/index.html')));
            file = vault.adapter.getFullPath(file);
            // console.log(vault.getResourcePath(nFile as TFile));
            if (settings.debug) {
                console.log('entering server query');
                console.log(req);
                console.log(file);
            }
            // if (file.indexOf(dir + path.sep) !== 0) {
            //   res.statusCode = 403;
            //   res.setHeader('Content-Type', 'text/plain');
            //   return res.end('Forbidden');
            // }
            // @ts-ignore
            const type = mime[path.extname(file).slice(1)];
            const s = fs.createReadStream(file);
            s.on('open', function () {
                res.setHeader('Content-Type', type);
                res.setHeader('Access-Control-Allow-Origin', '*');
                s.pipe(res);
            });
            s.on('error', function () {
                console.log('Here3');
                res.setHeader('Content-Type', 'text/plain');
                res.statusCode = 404;
                res.end('Not found');
            });
        });
        try {
            const port = this.settings.imgServerPort;
            this.imgServer.listen(port, function () {
                console.log('Image server listening on http://localhost:' + port + '/');
            });
        }
        catch (e) {
            console.log(e);
            new obsidian.Notice('Neo4j: Couldn\'t start image server, see console');
        }
    }
    async onunload() {
        super.onunload();
        this.imgServer.close();
        this.imgServer = null;
    }
}

